diff --git a/lib/rules/no-unused-expressions.js b/lib/rules/no-unused-expressions.js
index 6529c0a..862679c 100644
--- a/lib/rules/no-unused-expressions.js
+++ b/lib/rules/no-unused-expressions.js
@@ -83,6 +83,46 @@ module.exports = {
 			},
 		] = context.options;

+		/**
+		 * Detects a directive-like statement: an unparenthesized string literal expression statement.
+		 * Used as a fallback for parsers that don't set `directive` (e.g. espree with `ecmaVersion: 3`).
+		 * @param {ASTNode} node any node
+		 * @returns {boolean} whether the given node structurally looks like a directive
+		 */
+		function looksLikeDirective(node) {
+			return (
+				node.type === "ExpressionStatement" &&
+				node.expression.type === "Literal" &&
+				typeof node.expression.value === "string" &&
+				node.expression.range[0] === node.range[0]
+			);
+		}
+
+		/**
+		 * Detect if a node is a directive.
+		 * @param {ASTNode} node an ExpressionStatement node
+		 * @returns {boolean} whether the node is a directive in its current position
+		 */
+		function isDirective(node) {
+			if (astUtils.isDirective(node)) {
+				return true;
+			}
+
+			// Only `FunctionBody`, `ScriptBody` and `ModuleBody` can have a directive prologue.
+			if (!astUtils.isTopLevelExpressionStatement(node)) {
+				return false;
+			}
+			for (const statement of node.parent.body) {
+				if (statement === node) {
+					return looksLikeDirective(node);
+				}
+				if (!looksLikeDirective(statement)) {
+					return false;
+				}
+			}
+			return false;
+		}
+
 		/**
 		 * The member functions return `true` if the type has no side-effects.
 		 * Unknown nodes are handled as `false`, then this rule ignores those.
@@ -154,7 +194,7 @@ module.exports = {
 			ExpressionStatement(node) {
 				if (
 					Checker.isDisallowed(node.expression) &&
-					!astUtils.isDirective(node)
+					!isDirective(node)
 				) {
 					context.report({ node, messageId: "unusedExpression" });
 				}
diff --git a/tests/lib/rules/no-unused-expressions.js b/tests/lib/rules/no-unused-expressions.js
index 775e253..fc2d969 100644
--- a/tests/lib/rules/no-unused-expressions.js
+++ b/tests/lib/rules/no-unused-expressions.js
@@ -113,6 +113,24 @@ ruleTester.run("no-unused-expressions", rule, {
 			options: [{ enforceForJSX: true }],
 			languageOptions: { parserOptions: { ecmaFeatures: { jsx: true } } },
 		},
+
+		// directives in ecmaVersion 3, where espree doesn't set `directive`
+		{
+			code: '"use strict";',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		},
+		{
+			code: '"directive one"; "directive two"; f();',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		},
+		{
+			code: 'function foo() {"use strict"; return true; }',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		},
+		{
+			code: 'function foo() { "a"; "b"; return 1; }',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		},
 	],
 	invalid: [
 		{
@@ -354,6 +372,52 @@ ruleTester.run("no-unused-expressions", rule, {
 				},
 			],
 		},
+
+		// a parenthesized string is not a directive
+		{
+			code: '("use strict");',
+			errors: [
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+			],
+		},
+
+		// directives in ecmaVersion 3, where espree doesn't set `directive`
+		{
+			code: 'f(); "use strict";',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+			errors: [
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+			],
+		},
+		{
+			code: 'function foo() { var foo = true; "use strict"; }',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+			errors: [
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+			],
+		},
+		{
+			code: '("use strict");',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+			errors: [
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+			],
+		},
+		{
+			code: '"use strict"; ("not directive"); "also not";',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+			errors: [
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+			],
+		},
+		{
+			code: '{ "use strict"; }',
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+			errors: [
+				{ messageId: "unusedExpression", type: "ExpressionStatement" },
+			],
+		},
 	],
 });
